-- Product details screen (mobile):
--   colors              → swatches; [{ "name_ar": "أوليف", "hex": "#6F7D5C" }]
--   sizes               → capacity / size / weight chips; [{ "label": "128 جيجا", "price_delta": -2500 }]
--   default_size_index  → preselected entry in sizes
--   specs               → المواصفات table; [{ "label": "الشاشة", "value": "6.7 بوصة" }]
--   highlights_ar       → bullet list under الوصف
--   product_media.color_hex / view → gallery photos per colour ("hero", "back", "angle", "detail", "scene", "pack")
alter table public.products
  add column if not exists colors jsonb not null default '[]'::jsonb,
  add column if not exists sizes jsonb not null default '[]'::jsonb,
  add column if not exists default_size_index integer,
  add column if not exists specs jsonb not null default '[]'::jsonb,
  add column if not exists highlights_ar text[] not null default '{}';

alter table public.product_media
  add column if not exists color_hex varchar(9),
  add column if not exists view varchar(16);

update public.products p
set colors = d.colors, sizes = d.sizes, default_size_index = d.default_size, specs = d.specs, highlights_ar = d.hl
from (
  values
  ('iphone-15-128', '[{"name_ar":"أسود","hex":"#2B2F45"},{"name_ar":"أزرق","hex":"#9FB8D6"},{"name_ar":"بينك","hex":"#E9C4CF"}]'::jsonb,
