delete from public.product_media m
using public.products p
where m.product_id = p.id and p.slug in ('samsung-galaxy-a56-5g-256', 'xiaomi-redmi-note-14-pro-256', 'merchant-realme-c75', 'anker-soundcore-p20i', 'jbl-tune-520bt', 'xiaomi-smart-band-9', 'anker-powercore-20000', 'zahran-granite-cookware-10', 'tornado-airfryer-5-5l', 'salma-crepe-abaya', 'cottonil-egyptian-cotton-tee', 'activ-running-sneaker', 'eva-vitamin-c-serum-30', 'abu-auf-turkish-coffee-250', 'crystal-sunflower-oil-2-2l', 'speed-king-rc-car-4x4');

